  (1, 'Glendale Community College', '32607', 44763682085, '{"blocks":[{"courses":[{"alternatives":[{"catalog_addition":false,"code":"ANTHR 110","units":3}],"catalog_addition":false,"code":"ANTHR 101","units":4,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"ANTHR 102H","units":3}],"catalog_addition":false,"code":"ANTHR 102","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ANTHR 150","units":3,"units_max":null}],"minimum":null,"name":"REQUIRED COURSES FOR MAJOR","option_group":null,"rule":"all","stated":{"max":null,"min":null}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"ANTHR 104","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ANTHR 105","units":3,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"STAT C1000","units":4},{"catalog_addition":false,"code":"STAT C1000E","units":5},{"catalog_addition":false,"code":"STAT C1000H","units":4}],"catalog_addition":false,"code":"ECON 127","units":4,"units_max":null}],"minimum":1,"name":"LIST A - CHOOSE ONE OF THE FOLLOWING","option_group":null,"rule":"choose_courses","stated":{"max":null,"min":null}},{"courses":[{"alternatives":[{"catalog_addition":false,"code":"SOC 200","units":3.5}],"catalog_addition":false,"code":"PSYC 200","units":4,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"GEOL 101H","units":3}],"catalog_addition":false,"code":"GEOL 101","units":3,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"GEOL 111H","units":1}],"catalog_addition":false,"code":"GEOL 111","units":1,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"GEOG 155","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"BIOL 120","units":5,"units_max":null}],"minimum":1,"name":"LIST B - CHOOSE ONE OR TWO OF THE FOLLOWING","option_group":null,"rule":"choose_courses","stated":{"max":null,"min":null}},{"courses":[{"alternatives":[],"catalog_addition":f