  (2, 'Glendale Community College', '36416', 43415972509, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":false,"code":"MATH 103E","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MATH 104E","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MATH 105","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MATH 108","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"PHY 101","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"PHY 102","units":5,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"CHEM 101","units":5,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"GEOL 101","units":3},{"catalog_addition":false,"code":"GEOL 111","units":1},{"catalog_addition":false,"code":"GEOL 102","units":3},{"catalog_addition":false,"code":"GEOL 112","units":1},{"catalog_addition":false,"code":"OCEAN 115","units":3},{"catalog_addition":false,"code":"OCEAN 116","units":1}],"catalog_addition":true,"code":"BIOL 122","units":4,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 100","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 122","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 140","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 141","units":1,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 152","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 156","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 230","units":4,"units_max":null},{"alternatives":[{"catalog_addition":false,"code":"ENGR 240","units":4}],"catalog_addition":false,"code":"ENGR 180","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"ENGR 241","units":3,"units_max":null}],"mi